logger.message:
#[
import try from dw::Runtime
import java!java::lang::Class
import java!java::lang::Thread
output application/java
fun sqlException(t) = do {
  var clazz = try(() -> Class::forName(t.^class as String, false, Thread::currentThread().contextClassLoader)).result default null
  var ancestry = (1 to 16) reduce ((step, a = {clazz: clazz, found: false}) ->
    if (a.found or a.clazz == null) a else {
      clazz: try(() -> a.clazz.superclass).result default null,
      found: (try(() -> a.clazz.name).result default '') == 'java.sql.SQLException'
    })
  --- ancestry.found
}
var diagnostic = try(() -> do {
  var chain = (1 to 16) reduce ((step, a = {cause: error.cause, sql: null}) ->
    if (a.sql != null or a.cause == null) a
    else if (sqlException(a.cause)) {cause: null, sql: a.cause}
    else {cause: try(() -> a.cause.cause).result default null, sql: null})
  var sql = chain.sql
  var raw = if (sql == null) 'SQL cause unavailable' else (try(() -> sql.message as String).result default 'SQL message unavailable')
  var safeMessage = if ([
    'EVENT_ID_CONFLICT_OR_LEGACY_ROW', 'INVALID_ALERT_WINDOW',
    'SQL cause unavailable', 'SQL message unavailable'
  ] contains raw) raw else 'SQL message withheld (not allowlisted)'
  --- {
    eventId: modules::Masking::sanitize(vars.eventId default 'unknown'),
    correlationId: modules::Masking::sanitize(vars.corrId default correlationId),
    sqlMessage: (safeMessage replace /[\r\n\t]/ with ' ')[0 to 511],
    SQLState: try(() -> sql.SQLState as String).result default 'unavailable',
    vendorErrorCode: try(() -> sql.errorCode as Number).result default null
  }
})
---
try(() -> 'PERSISTENCE_SQL_FAILURE ' ++ write(diagnostic.result default {
  eventId: modules::Masking::sanitize(vars.eventId default 'unknown'),
  correlationId: modules::Masking::sanitize(vars.corrId default correlationId),
  sqlMessage: 'SQL diagnostic unavailable', SQLState: 'unavailable', vendorErrorCode: null
}, 'application/json', {indent: false})).result default 'PERSISTENCE_SQL_FAILURE {"eventId":"unavailable","correlationId":"unavailable","sqlMessage":"SQL diagnostic unavailable","SQLState":"unavailable","vendorErrorCode":null}'
]
